// Load a DLL and report what the loader did with it.
//
// Usage: loadone <dll-path> [export-name]
//
// Prints the LoadLibrary error code on failure. On success it resolves an
// optional export and reports which module the address lives in, which is
// how an ARM64X forwarder is checked: the native ARM64 slice must resolve
// into the ARM64 backend, the emulated x64 slice into the x64 backend.
#include <Windows.h>
#include <stdio.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: loadone <dll> [export]\n");
        return 2;
    }
    SetLastError(0);
    HMODULE h = LoadLibraryExA(argv[1], NULL, LOAD_WITH_ALTERED_SEARCH_PATH);
    if (!h) {
        DWORD e = GetLastError();
        printf("FAIL LoadLibrary(%s) error=%lu\n", argv[1], e);
        return 1;
    }
    printf("OK   LoadLibrary(%s) handle=%p\n", argv[1], (void *)h);

    if (argc >= 3) {
        FARPROC p = GetProcAddress(h, argv[2]);
        if (!p) {
            printf("FAIL GetProcAddress(%s) error=%lu\n", argv[2],
                   GetLastError());
            return 1;
        }
        HMODULE owner = NULL;
        GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
                               GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                           (LPCSTR)p, &owner);
        char path[MAX_PATH] = {0};
        GetModuleFileNameA(owner, path, MAX_PATH);
        printf("     %s -> %p in %s\n", argv[2], (void *)p, path);
    }
    FreeLibrary(h);
    return 0;
}
